/// <summary>
/// AVA Stephan Schneider 19.10.22
///     The <c>LogisticsPostalAddressFrm_LogisticsPostalAddress_CityFld_Extension</c> class is the extension for <c>LogisticsPostalAddress</c>
/// </summary>
[ExtensionOf(formControlStr(LogisticsPostalAddress, LogisticsPostalAddress_City))]
final class LogisticsPostalAddressFrm_LogisticsPostalAddress_CityFld_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean                     retVal;

    FormStringControl           locFormStringControlZIP;
    LogisticsAddressZipCodeId   locLogisticsAddressZipCodeId;
    FormStringControl           locFormStringControlCity;
    LogisticsAddressCityName    locLogisticsAddressCityName;


    retVal = next modified();

    locFormStringControlZIP         = element.LogisticsPostalAddress_ZipCode;
    locLogisticsAddressZipCodeId    = locFormStringControlZIP.valueStr();
    locFormStringControlCity        = element.LogisticsPostalAddress_City;
    locLogisticsAddressCityName     = locFormStringControlCity.valueStr();

    if (locLogisticsAddressCityName != '' && locLogisticsAddressZipCodeId == '')
    {
        locFormStringControlZIP.mandatory(true);
    }
    else
    {
        locFormStringControlZIP.mandatory(false);
    }

    return retVal;
}
